1016	+      durationSeconds = current.durationSeconds!;
1017	+      text = current.text!.trim();
1018	+    } else {
1019	+      return;
1020	+    }
1021	+    if (text.isEmpty) {
1022	+      return;
1023	+    }
1024	+    emit(
1025	+      AudioTranscribed(
1026	+        path: path,
1027	+        durationSeconds: durationSeconds,
1028	+        text: text,
1029	+        saving: true,
1030	+      ),
1031	+    );
